#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <ctype.h>

#define VOCAB_SIZE 50257
#define EMBED_DIM 768
#define NUM_HEADS 12
#define NUM_LAYERS 12
#define MAX_SEQ 1024

typedef struct {
    float *wte, *wpe, *ln_f_w, *ln_f_b;
    float *h_ln_w[NUM_LAYERS], *h_ln_b[NUM_LAYERS];
    float *h_attn_w[NUM_LAYERS], *h_mlp_w[NUM_LAYERS];
} Model;

typedef struct {
    int *tokens;
    int len;
} TokenSeq;

Model model;
int vocab[50001];
int vocab_len = 0;

void load_vocab(const char *path) {
    FILE *f = fopen(path, "r");
    char line[256];
    vocab_len = 0;
    while (fgets(line, sizeof(line), f) && vocab_len < 50001) {
        line[strcspn(line, "\n")] = 0;
        if (line[0] == '#') continue;
        vocab[vocab_len++] = vocab_len;
    }
    fclose(f);
}

void load_checkpoint(const char *path) {
    FILE *f = fopen(path, "rb");
    fseek(f, 0, SEEK_END);
    long size = ftell(f);
    fseek(f, 0, SEEK_SET);

    float *data = malloc(size);
    fread(data, 1, size, f);
    fclose(f);

    model.wte = data;
    int offset = VOCAB_SIZE * EMBED_DIM;
    model.wpe = data + offset;

    free(data);
}

int argmax(float *logits, int n) {
    int idx = 0;
    float max_val = logits[0];
    for (int i = 1; i < n; i++) {
        if (logits[i] > max_val) {
            max_val = logits[i];
            idx = i;
        }
    }
    return idx;
}

void forward(TokenSeq *seq, float *output) {
    memset(output, 0, VOCAB_SIZE * sizeof(float));
    if (seq->len > 0) {
        int last_token = seq->tokens[seq->len - 1];
        if (last_token >= 0 && last_token < VOCAB_SIZE) {
            float *embed = model.wte + last_token * EMBED_DIM;
            for (int i = 0; i < VOCAB_SIZE && i < EMBED_DIM; i++) {
                output[i] = embed[i];
            }
        }
    }
}

int main(int argc, char *argv[]) {
    if (argc < 4) return 1;

    load_checkpoint(argv[1]);
    load_vocab(argv[2]);

    TokenSeq seq;
    seq.len = 0;
    seq.tokens = malloc(MAX_SEQ * sizeof(int));

    char *input = argv[3];
    seq.len = strlen(input);
    for (int i = 0; i < seq.len; i++) {
        seq.tokens[i] = (unsigned char)input[i] % VOCAB_SIZE;
    }

    float *logits = malloc(VOCAB_SIZE * sizeof(float));

    for (int step = 0; step < 20; step++) {
        forward(&seq, logits);
        int next_token = argmax(logits, VOCAB_SIZE);

        if (next_token < 128) {
            printf("%c", (char)next_token);
        } else {
            printf("<%d>", next_token);
        }

        if (seq.len < MAX_SEQ) {
            seq.tokens[seq.len++] = next_token;
        }
    }

    printf("\n");
    free(logits);
    free(seq.tokens);
    return 0;
}
