void matmul(float *a, float *b, float *c, int m, int n, int k) {
    for (int i = 0; i < m; i++)
        for (int j = 0; j < n; j++) {
            c[i*n+j] = 0;
            for (int p = 0; p < k; p++)
                c[i*n+j] += a[i*k+p] * b[p*n+j];
        }
}

int argmax(float *x, int n) {
    int idx = 0;
    float maxv = x[0];
    for (int i = 1; i < n; i++)
        if (x[i] > maxv) { maxv = x[i]; idx = i; }
    return idx;
}

