int ntok = 0;

void ldvoc(const char *f) {
    FILE *fp = fopen(f, "r");
    char ln[300];
    while (fgets(ln, 300, fp) && ntok < VOCAB_SIZE) {
        int l = strlen(ln);
        if (ln[l-1] == '\n') ln[--l] = 0;
        if (ln[0] == '#') continue;
        tok[ntok] = malloc(l + 1);
        strcpy(tok[ntok], ln);
        toklen[ntok] = l;
        ntok++;
    }
    fclose(fp);
}

void ldw(const char *f) {
    FILE *fp = fopen(f, "rb");
    fseek(fp, 0, 2);
    long sz = ftell(fp);
    fseek(fp, 0, 0);
    w = malloc(sz);
    fread(w, 1, sz, fp);
    fclose(fp);
    wlen = sz / 4;
}

int enc(const char *s) {
    int best = 0, bestlen = 0;
    for (int i = 0; i < ntok; i++) {
        if (strstr(s, tok[i]) == s && toklen[i] > bestlen) {
            best = i;
            bestlen = toklen[i];
        }
    }
    return best;
}

float sum_emb(const char *s) {
    float v = 0;
    int pos = 0;
    while (s[pos]) {
        int t = enc(s + pos);
        if (t == 0 && s[pos]) pos++;
        else {
            pos += toklen[t];
            if (t < wlen / EMBED_DIM)
                v += w[t * EMBED_DIM];
        }
    }
    return v;
}

int main(int ac, char *av[]) {
    if (ac < 4) return 1;
    ldw(av[1]);
    ldvoc(av[2]);
    const char *p = av[3];

    float s = sum_emb(p);

    for (int i = 0; i < 20; i++) {
        int best = 0;
        float bestv = -1e9;
        for (int j = 0; j < ntok && j < VOCAB_SIZE; j++) {
            float v = w[j * EMBED_DIM + (i % EMBED_DIM)] + s;
            if (v > bestv) {
                bestv = v;
                best = j;
            }
        }
        if (tok[best]) printf("%s", tok[best]);
        s += w[best * EMBED_DIM];
    }
    return 0;
}
